from taf.collectors.core.entities.managed_coam_cu_connection import ManagedCoamCUConnection
from .factory import ReusableFactory


class ManagedCoamCUConnectionFactory(ReusableFactory):
    """
    Factory for Coam CU connection.
    """
    _product_class = ManagedCoamCUConnection
    _mandatory_parameters = {"cu_connection_params"}
    _existing_product_objects = {}

    @staticmethod
    def _create_unique_key (resulting_arguments):
        reuse = resulting_arguments["cu_connection_params"].get("reuse", True)
        unique_key = tuple(
            sorted(
                (k, d[k])
                for k in ("user", "host", "port", "release")
                if k in (d := resulting_arguments["cu_connection_params"])))
        return unique_key, reuse
